/* HEXA BATTLEGROUNDS setup — PART 48 OF 57. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-safe-24', 'safe', 'battle', 'Safe Cracker Duel', 'logic', 2, array['duel_sniper']::text[], 'A 3-digit lock. Each teammate holds some of the lock’s clues. Together they point to exactly one code. Digits never repeat.', '{"scout":{"title":"Lock clues A","body":"7 5 0\n  → nothing is correct\n1 4 9\n  → 2 correct, wrong place","mono":true},"decoder":{"title":"Lock clues B","body":"7 4 6\n  → nothing is correct\n2 5 6\n  → 1 correct, wrong place","mono":true},"intel":{"title":"Lock clues C","body":"2 9 8\n  → 2 correct, wrong place\n7 2 6\n  → 1 correct, wrong place\n\nThe code has 3 different digits.","mono":true}}'::jsonb, '[{"label":"3-digit code","accept":["912"]}]'::jsonb, false, 3, 120, 'Start with "Nothing is correct" lines: cross those digits out everywhere. Then test the remaining digits against each clue.', 'Only 912 fits every clue.', null, 25, 'published'), ('mission-morse-0', 'morse', 'mission', 'Radio Morse', 'decoding', 2, array['any','transmission','access','gate','observation','terrace']::text[], 'A Morse signal came over the squad radio. Scout copied it; Decoder holds letters A–M and Intel letters N–Z. Decode the word.', '{"scout":{"title":"Intercepted signal","body":"−−··   /   −−−   /   −·   /   ·\n\n(4 letters, “/” separates letters)","mono":true,"big":true},"decoder":{"title":"Codebook A–M","body":"A ·−\nB −···\nC −·−·\nD −··\nE ·\nF ··−·\nG −−·\nH ····\nI ··\nJ ·−−−\nK −·−\nL ·−··\nM −−","mono":true},"intel":{"title":"Codebook N–Z","body":"N −·\nO −−−\nP ·−−·\nQ −−·−\nR ·−·\nS ···\nT −\nU ··−\nV ···−\nW ·−−\nX −··−\nY −·−−\nZ −−··","mono":true}}'::jsonb, '[{"label":"Decoded word","accept":["ZONE"]}]'::jsonb, false, 3, 200, '· is a short beep, − is a long beep. Read one lett